#!/usr/bin/env python3

"""Comprehensive test script for MySQL JSON_VALUE function support."""

from sqlglot.dialects.mysql import MySQL
from sqlglot import parse_one

def test_cases():
    """Test various JSON_VALUE scenarios."""

    test_cases = [
        # Basic case - should work after fix
        {
            "name": "Basic JSON_VALUE with RETURNING",
            "sql": """SELECT JSON_VALUE('{"item": "shoes", "price": "49.95"}', '$.price' RETURNING DECIMAL(4,2)) AS price""",
            "should_work": True
        },

        # Basic case without RETURNING - should work even before fix if we add basic support
        {
            "name": "Basic JSON_VALUE without RETURNING",
            "sql": """SELECT JSON_VALUE('{"item": "shoes", "price": "49.95"}', '$.price') AS price""",
            "should_work": False  # Won't work until we implement basic JSON_VALUE
        },

        # With ON EMPTY clause
        {
            "name": "JSON_VALUE with ON EMPTY",
            "sql": """SELECT JSON_VALUE('{"item": "shoes", "price": "49.95"}', '$.discount' RETURNING DECIMAL(4,2) DEFAULT 0 ON EMPTY) AS discount""",
            "should_work": True
        },

        # With ON ERROR clause
        {
            "name": "JSON_VALUE with ON ERROR",
            "sql": """SELECT JSON_VALUE('{"item": "shoes", "price": "49.95"}', '$.price' RETURNING DECIMAL(4,2) ERROR ON ERROR) AS price""",
            "should_work": True
        },

        # With both ON EMPTY and ON ERROR
        {
            "name": "JSON_VALUE with both ON clauses",
            "sql": """SELECT JSON_VALUE('{"item": "shoes", "price": "49.95"}', '$.invalid' RETURNING DECIMAL(4,2) DEFAULT 0 ON EMPTY NULL ON ERROR) AS result""",
            "should_work": True
        },

        # Different RETURNING types
        {
            "name": "JSON_VALUE with RETURNING VARCHAR",
            "sql": """SELECT JSON_VALUE('{"name": "John", "age": 30}', '$.name' RETURNING VARCHAR(50)) AS name""",
            "should_work": True
        },

        # In WHERE clause
        {
            "name": "JSON_VALUE in WHERE clause",
            "sql": """SELECT * FROM products WHERE JSON_VALUE(attributes, '$.color' RETURNING VARCHAR(20)) = 'red'""",
            "should_work": True
        }
    ]

    results = []

    for i, test_case in enumerate(test_cases, 1):
        print(f"\n{i}. Testing: {test_case['name']}")
        print(f"SQL: {test_case['sql']}")

        try:
            ast = parse_one(test_case['sql'], dialect=MySQL)
            print("✓ SUCCESS: Parsed correctly")
            print(f"  AST: {type(ast).__name__}")
            results.append(True)
        except Exception as e:
            if test_case['should_work']:
                print(f"✗ FAILED (expected to work): {type(e).__name__}: {e}")
                results.append(False)
            else:
                print(f"• EXPECTED FAILURE: {type(e).__name__}: {e}")
                results.append(True)  # Expected failure is OK

    print(f"\n=== SUMMARY ===")
    passed = sum(results)
    total = len(results)
    print(f"Passed: {passed}/{total}")

    if passed == total:
        print("🎉 All tests passed!")
        return True
    else:
        print("❌ Some tests failed")
        return False

if __name__ == "__main__":
    test_cases()

